/// <summary>
/// Overrides inventSearch
/// </summary>
/// <returns>MCRInventSearch object</returns>
protected MCRInventSearch inventSearch()
{
    MCRInventSearch mcrInventSearch = next inventSearch();

    mcrInventSearch.parmIsSalesItem(isSalesItem.value());

    return mcrInventSearch;
}
